import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long c = 1000000007L;
        String[] input = scanner.nextLine().trim().split(" ");
        long p = Long.parseLong(input[0]);
        long k = Long.parseLong(input[1]);

        if (k == 0) {
            System.out.println(modPow(p, p - 1, c));
        } else if (k == 1) {
            System.out.println(modPow(p, p, c));
        } else {
            long n = k;
            long order = 1;
            while (n != 1) {
                n = (n * k) % p;
                order++;
            }
            long loops = (p - 1) / order;
            System.out.println(modPow(p, loops, c));
        }
        scanner.close();
    }

    private static long modPow(long base, long exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

